import { hmacSha256 } from './hmac.mjs';
import { base64urlEncode } from './base64url.mjs';
import { dumpsCompact } from './jsonDumps.mjs';

export function encodeJwt(claims, secret, algorithm = 'HS256') {
  const encoder = new TextEncoder();
  const header = { alg: algorithm, typ: 'JWT' };

  const headerBytes = encoder.encode(dumpsCompact(header));
  const payloadBytes = encoder.encode(dumpsCompact(claims));

  const signingInput = base64urlEncode(headerBytes) + '.' + base64urlEncode(payloadBytes);
  const signature = hmacSha256(encoder.encode(secret), encoder.encode(signingInput));

  return signingInput + '.' + base64urlEncode(signature);
}

