function hex4(n) {
  return n.toString(16).padStart(4, '0');
}

function encodeString(s) {
  let out = '"';
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code === 0x22) {
      out += '\\"';
    } else if (code === 0x5c) {
      out += '\\\\';
    } else if (code === 0x08) {
      out += '\\b';
    } else if (code === 0x0c) {
      out += '\\f';
    } else if (code === 0x0a) {
      out += '\\n';
    } else if (code === 0x0d) {
      out += '\\r';
    } else if (code === 0x09) {
      out += '\\t';
    } else if (code < 0x20 || code >= 0x7f) {
      out += '\\u' + hex4(code);
    } else {
      out += s[i];
    }
  }
  return out + '"';
}

export function dumpsCompact(value) {
  if (value === null || value === undefined) return 'null';
  const t = typeof value;
  if (t === 'string') return encodeString(value);
  if (t === 'boolean') return value ? 'true' : 'false';
  if (t === 'number') {
    if (!Number.isFinite(value)) {
      if (Number.isNaN(value)) return 'NaN';
      return value > 0 ? 'Infinity' : '-Infinity';
    }
    return String(value);
  }
  if (Array.isArray(value)) {
    return '[' + value.map(dumpsCompact).join(',') + ']';
  }
  if (t === 'object') {
    const parts = [];
    for (const key of Object.keys(value)) {
      parts.push(encodeString(key) + ':' + dumpsCompact(value[key]));
    }
    return '{' + parts.join(',') + '}';
  }
  throw new TypeError('Unsupported type: ' + t);
}

