// Minimal re-implementation of Python argparse behavior for this parser spec:
//   prog = basename of process.argv[1]
//   one required option `--payload` taking one string value, plus auto -h/--help
// parseArgs(argv) receives an array like process.argv.slice(2) and returns
// { payload: string }. Help/errors replicate CPython argparse byte-for-byte.

const LONG_OPTIONS = ['--help', '--payload'];
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function progName() {
  const script = process.argv[1] || '';
  const parts = script.split(/[\\/]/);
  return parts[parts.length - 1] || script;
}

function usageLine(prog) {
  return `usage: ${prog} [-h] --payload PAYLOAD\n`;
}

function helpText(prog) {
  return (
    usageLine(prog) +
    '\n' +
    'options:\n' +
    '  -h, --help         show this help message and exit\n' +
    '  --payload PAYLOAD\n'
  );
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog));
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelpAndExit(prog) {
  process.stdout.write(helpText(prog));
  process.exit(0);
}

// argparse treats a token as option-like if it starts with '-' and is not a
// negative number (a lone '-' is a value, conventionally stdin).
function looksLikeOption(token) {
  if (token.length === 0 || token[0] !== '-') return false;
  if (token === '-') return false;
  if (NEGATIVE_NUMBER.test(token)) return false;
  return true;
}

export function parseArgs(argv) {
  const prog = progName();
  let payload;
  let havePayload = false;
  const extras = [];
  let optionsEnded = false;

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (!optionsEnded && token === '--') {
      optionsEnded = true;
      i += 1;
      continue;
    }

    if (!optionsEnded && token.startsWith('--')) {
      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);
      const explicit = eq === -1 ? null : token.slice(eq + 1);

      let matched = null;
      if (LONG_OPTIONS.includes(name)) {
        matched = name;
      } else {
        const candidates = LONG_OPTIONS.filter((o) => o.startsWith(name));
        if (candidates.length === 1) {
          matched = candidates[0];
        } else if (candidates.length > 1) {
          fail(prog, `ambiguous option: ${name} could match ${candidates.join(', ')}`);
        }
      }

      if (matched === '--help') {
        if (explicit !== null) {
          fail(prog, `argument -h/--help: ignored explicit argument '${explicit}'`);
        }
        printHelpAndExit(prog);
      } else if (matched === '--payload') {
        if (explicit !== null) {
          payload = explicit;
          havePayload = true;
        } else if (i + 1 < argv.length && !looksLikeOption(argv[i + 1])) {
          payload = argv[i + 1];
          havePayload = true;
          i += 1;
        } else {
          fail(prog, 'argument --payload: expected one argument');
        }
      } else {
        extras.push(token);
      }
      i += 1;
      continue;
    }

    if (!optionsEnded && token === '-h') {
      printHelpAndExit(prog);
    }

    // Unknown short options and stray positionals collect as unrecognized.
    extras.push(token);
    i += 1;
  }

  // argparse reports missing required arguments before unrecognized ones.
  if (!havePayload) {
    fail(prog, 'the following arguments are required: --payload');
  }
  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { payload };
}

