  { args: ['--payload', 'x', '-h'], stdout: help, stderr: '', code: 0 },
  { args: ['--unknown', '-h'], stdout: help, stderr: '', code: 0 },

  // (2) missing --payload -> stderr, exit 2
  { args: [], stdout: '', stderr: err('the following arguments are required: --payload'), code: 2 },
  { args: ['--unknown', 'x'], stdout: '', stderr: err('the following arguments are required: --payload'), code: 2 },

  // (3) --payload with no value / option-like next token
  { args: ['--payload'], stdout: '', stderr: err('argument --payload: expected one argument'), code: 2 },
  { args: ['--payload', '--unknown'], stdout: '', stderr: err('argument --payload: expected one argument'), code: 2 },
